import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"FR 3.5.5 - Create Media Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-5-create-media-campaign/spec.md","filePath":"feature/media-package-campaign/3-5-5-create-media-campaign/spec.md"}'),r={name:"feature/media-package-campaign/3-5-5-create-media-campaign/spec.md"};function i(c,e,s,d,p,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="fr-3-5-5-create-media-campaign" tabindex="-1">FR 3.5.5 - Create Media Campaign <a class="header-anchor" href="#fr-3-5-5-create-media-campaign" aria-label="Permalink to &quot;FR 3.5.5 - Create Media Campaign&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Implemented in code; live API/concurrency verification pending (2026-10-10)</td></tr><tr><td>Roles</td><td>Owner/Manager</td></tr><tr><td>Delivery task</td><td>DA-E50-06 / DA-947</td></tr></tbody></table><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>&gt; Current implementation uses Workspace-scoped create/list/detail/PATCH endpoints. &gt; The earlier <code>/api/v1/media-campaigns</code> create route remains compatible and also &gt; enforces one Campaign per agreement and total quantities. Frozen terms, work items &gt; and content versions are persisted; live verification remains in the &gt; <a href="./../implementation-roadmap.html">roadmap</a>.</p><p>Owner/Manager creates a <code>DRAFT</code> campaign from an approved workspace package. The campaign is an execution plan, not a contract.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li><code>POST /api/v1/workspaces/{workspaceId}/campaigns</code> rejects an unapproved package with <code>PACKAGE_NOT_APPROVED</code>.</li><li>A campaign stores name, strategy detail, brand guideline, timeline, status, <code>contentVersion</code>, approvals, and JSONB <code>workItems</code>.</li><li>Each work item has stable <code>id</code>, <code>deliverableId</code>, <code>name</code>, <code>type</code> (<code>POST|LIVESTREAM|SURVEY|EVENT_PLAN|PRESS_RECOMMENDATION</code>) and <code>dueDate</code>, so deployment creates one task exactly once.</li><li>A Workspace has at most one Campaign, including DRAFT and COMPLETED. A new campaign uses a new Workspace; an Owner duplication feature is planned separately.</li><li>Keep one selected WorkspaceMediaPackage per Workspace. Do not implement multiple cooperation rounds or allow agreement reassignment to bypass Campaign uniqueness.</li><li>New packages use total quantities for the whole package, with no monthly allowance. Legacy monthly snapshots remain unchanged and require explicit handling, not automatic conversion. See <a href="./../phase-1-design/plan.html">phase-1 contract</a> for fields/API and migration gates.</li></ul><h2 id="constraint" tabindex="-1">Constraint <a class="header-anchor" href="#constraint" aria-label="Permalink to &quot;Constraint&quot;">​</a></h2><p>Task IDs are not a substitute for planned work items: tasks exist only after deployment. <code>workItems</code> is stored in PostgreSQL JSONB and is the deployment source of truth.</p><h2 id="approval-version-rule" tabindex="-1">Approval-version rule <a class="header-anchor" href="#approval-version-rule" aria-label="Permalink to &quot;Approval-version rule&quot;">​</a></h2><p>The campaign starts at content version 1. Editing campaign content or work items before final approval increments the version and invalidates both prior approvals; content is immutable once both parties approve.</p>',11)])])}const u=a(r,[["render",i]]);export{h as __pageData,u as default};
